import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.Iterator;
import java.util.LinkedList;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

public class Main {
    public static void main(String[] args) {
        // 1. ArrayList 扩容与预设容量
        ArrayList<Integer> withCap = new ArrayList<>(4);
        withCap.addAll(List.of(1, 2, 3, 4));
        System.out.println("预设容量 4, size=" + withCap.size()); // 无扩容

        // 2. LinkedList 按 index 操作的定位成本
        LinkedList<Integer> linked = new LinkedList<>();
        for (int i = 0; i < 1000; i++) linked.add(i);
        long t1 = System.nanoTime();
        linked.get(999); // 从尾部遍历
        long t2 = System.nanoTime();
        linked.get(0); // 从头部遍历
        long t3 = System.nanoTime();
        System.out.println("LinkedList get(999)=" + (t2 - t1) + "ns, get(0)=" + (t3 - t2) + "ns");

        // 3. ArrayDeque 做队列
        ArrayDeque<Integer> deque = new ArrayDeque<>();
        deque.offerLast(1); deque.offerLast(2); deque.offerLast(3);
        System.out.println("ArrayDeque FIFO: " + deque.pollFirst() + "," + deque.pollFirst() + "," + deque.pollFirst());

        // 4. fail-fast：for-each 中直接 remove
        boolean failFast = false;
        ArrayList<Integer> unsafe = new ArrayList<>(List.of(1, 2, 3, 4));
        try {
            for (Integer x : unsafe) {
                if (x == 2) unsafe.remove(x); // modCount 变化，迭代器下次检查抛异常
            }
        } catch (ConcurrentModificationException e) {
            failFast = true;
        }
        System.out.println("fail-fast: " + failFast);
        assert failFast;

        // 5. 安全删除：removeIf
        ArrayList<Integer> safe = new ArrayList<>(List.of(1, 2, 3, 4));
        safe.removeIf(x -> x % 2 == 0);
        System.out.println("removeIf 结果: " + safe);
        assert safe.equals(List.of(1, 3));

        // 6. CopyOnWriteArrayList 快照语义
        CopyOnWriteArrayList<Integer> cow = new CopyOnWriteArrayList<>(List.of(1, 2));
        Iterator<Integer> snapshot = cow.iterator(); // 拿到当前数组快照
        cow.add(3); // 写触发数组复制
        List<Integer> seen = new ArrayList<>();
        snapshot.forEachRemaining(seen::add);
        System.out.println("COW snapshot: " + seen + " (不包含 3), current: " + cow);
        assert seen.equals(List.of(1,2));
        assert cow.equals(List.of(1,2,3));
    }
}
